func (m model) View() tea.View {
	var v tea.View
	var body string

	n := len(m.dialogs)
	if n > 0 {
		body += "Drag to move. "
	}
	if n == 0 && n < maxDialogs {
		body += "Click to spawn."
	} else if n >= 1 && n < maxDialogs {
		body += fmt.Sprintf("Click to spawn up to %d more.", maxDialogs-len(m.dialogs))
	}
	body += "\n\nPress q to quit."

	bg := lipgloss.Place(
		m.width,
		m.height,
		lipgloss.Top,
		lipgloss.Left,
		bgTextStyle.Render(body),
		bgWhitespace...,
	)

	root := lipgloss.NewLayer(bg).ID("bg")
	for i, d := range m.dialogs {
		root.AddLayers(d.view().Z(i + 1))
	}

	comp := lipgloss.NewCompositor(root)

	v.MouseMode = tea.MouseModeAllMotion
	v.AltScreen = true
	v.OnMouse = func(msg tea.MouseMsg) tea.Cmd {
		return func() tea.Msg {
			mouse := msg.Mouse()
			x, y := mouse.X, mouse.Y
			if id := comp.Hit(x, y).ID(); id != "" {
				return LayerHitMsg{
					ID:	id,
					Mouse:	msg,
				}
			}
			return nil
		}
	}
	v.SetContent(comp.Render())

	return v
}
