	i1 := int(math.Floor(idx))
	i2 := int(math.Ceil(idx))

	i1 = i1 % len(colors)
	i2 = i2 % len(colors)
	if i1 < 0 {
		i1 += len(colors)
	}
	if i2 < 0 {
		i2 += len(colors)
	}

	t := idx - float64(i1)
	return interpolateColors(colors[i1], colors[i2], t)
}
