	dst := idx - rnd + 1
	if dst-m.width >= 0 && dst-m.width < len(m.screenBuf) {
		decay := rnd & 1
		newValue := max(pixel-decay, 0)
		m.screenBuf[dst-m.width] = newValue
	}
